class Solution { fun primePalindrome(n:Int):Int{if(n in 8..11)return 11;var prefix=1;while(true){val text=prefix.toString();val value=(text+text.dropLast(1).reversed()).toInt();if(value>=n&&prime(value))return value;prefix++}};private fun prime(value:Int):Boolean{if(value<2)return false;var divisor=2;while(divisor.toLong()*divisor<=value){if(value%divisor==0)return false;divisor++};return true} }
